function aitoHtml(text) {
    text = text.replace(/<think>[\s\S]+?<\/think>/,'');    
    if(!text)return "正在分析中......";    
    let lines = text.split(/<br>|\n/).filter(line => line.trim() !== '');
    let html = '';
    let currentListType = null;
    let inTable = false;
    let tableContent = '';
    let inBlock = false;
    let blockType = '';
    let blockContent = '';
    for(let i=0;i<lines.length;i++){
        let line = lines[i];
        let content="";
        if(!line)continue;
        if(line.startsWith('## ')){
            content = line.replace(/^## /g,'');
            content = `<h3 class="ai-h3">${content}</h2>`;
            html += content
        }
        else if(line.startsWith('### ')){
            content = line.replace(/^### /g,'');
            content = `<h3 class="ai-h3">${content}</h3>`;
            html += content
        }
        else if(line.startsWith('#### ')){
            content = line.replace(/^#### /g,'');
            content = `<h4 class="ai-h4">${content}</h4>`;
            html += content
        }
       else if(/^(?:\s*- |● )/.test(line)){
        	    content = line.replace(/^\s*- |^● /g,''); 	    
        	    content = `<li class="ai-list">${content}</li>`;                         
            html += content
        }
        else if(/^\s*\|.*\|\s*$/.test(line) && !inTable){
        	    inTable = true;
        	    tableContent += line +"\n";
         }
         else if(inTable){
             if (line.match(/^\s*\|.*\|\s*$/)) {
                tableContent += line + '\n';
            } else {
                html += processTable(tableContent.trim());
                inTable = false;
                tableContent = '';
                i--;
            }
            continue;
         }

         else if(/^\d+\./.test(line)){
             content = `<p class="ai-listp">${line}</p>`;
             html += content
         }
         else{
                content = line.replace(/^> /g,'');
         	   content = `<p class="ai-content">${content}</p>`;
                html += content
         	}

    }

html = `<div id="ai-body">${inlineFormat(html)}</div>`
return html
}


function processTable(content) {
    const rows = content.split('\n').filter(row => row.trim());
    if (rows.length < 2) return `<pre>${content}</pre>`;

    let tableHTML = '<table class="data-table">';

    rows.forEach((row, index) => {
        if (row.match(/^\s*\|[-:\|]+\|\s*$/)) return;       
        const cells = row.split('|').filter(cell => cell.trim() !== '');
        if (cells.length === 0) return;       
        if (index === 0) {          
            tableHTML += '<thead class="ai-thead"><tr class="ai-tr">';
            cells.forEach(cell => {
                tableHTML += `<th class="ai-th">${inlineFormat(cell.trim())}</th>`;
            });
            tableHTML += '</tr></thead><tbody class="ai-tbody">';
        } else {
            // 表体
            tableHTML += '<tr class="ai-tbody-tr">';
            cells.forEach(cell => {
                tableHTML += `<td class="ai-tbody-td">${inlineFormat(cell.trim())}</td>`;
            });
            tableHTML += '</tr>';
        }
    });

    tableHTML += '</tbody></table>';
    return tableHTML;
}

function inlineFormat(text) {

    let result = text.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');

    result = result.replace(/```.*?```/g,'')
                 .replace(/<media-block>/g,'<div class="media-block"><div class="media-c">')
                 .replace(/<\/media-block>/g,'</div></div>')
                 .replace(/data-scheme=".*?mid=(\d+)[^"]+"/g,`onclick="openContent('$1')"`)
                 .replace(/<span class="(?:vator|nick|arrow)"[^>]*?>[^<]*?<\/span>/g,'')
                 .replace(/data-width=\d+ data-height=\d+/g,'')
    return result;
}

function formatTime(dateStr) {
    const date = new Date(dateStr);
    const year = date.getFullYear();
    const month = date.getMonth() + 1; 
    const day = date.getDate();
    const hours = date.getHours().toString().padStart(2, '0');
    const minutes = date.getMinutes().toString().padStart(2, '0');

    return `${year}年${month}月${day}日 ${hours}:${minutes}`;
}

function formatCount(count) {
  if (count < 10000) return count.toString();  
  const inWan = (count / 10000).toFixed(2);
  return inWan.endsWith('.00') 
    ? `${inWan.split('.')[0]}万` 
    : `${inWan}万`;
}

