function getSuperUrl(name,url){
    let jsonAjax = java.ajax(url);
    let jsonData = JSON.parse(jsonAjax);
    let channel_list = jsonData.data.pageInfo.cardlist_head_cards[0].channel_list;
    let data = {};
    channel_list.forEach(tab=>{
         let u = `${m}/api/container/getIndex?containerid=`;
        if(tab.id == "feed"){
            data[name+"的📝帖子"] = u+tab.containerid+"&since_id=";
            data["📤帖子"] = u+tab.containerid.replace(/feed/,'sort_time')+"&since_id=";
            data["🔥帖子"] = u+tab.containerid.replace(/feed/,'recommend')+"&since_id=";
            data["💡帖子"] = u+tab.containerid.replace(/feed/,'soul')+"&since_id=";
        }else if(/\d+/.test(tab.id)){
            data["📝"+tab.name] = u+tab.containerid+"&since_id=";
            data["📤"+tab.name] = u+tab.containerid.replace(/comment_sort/,'status_sort')+"&since_id=";
        }else{
            data[tab.name] = u+tab.containerid+"&since_id=";
        }
    })

    return JSON.stringify(data)

}


