    async showPopup() {
        let overlay = document.getElementById('weibo-follow-overlay');
        let popup = document.getElementById('weibo-follow-popup');

        if (!popup || !overlay) {
            popup = this.createPopup();
            overlay = document.getElementById('weibo-follow-overlay');
        }

        overlay.style.display = 'block';
        popup.style.display = 'flex';
        document.body.style.overflow = 'hidden';

        this.users = [];
        this.selectedUsers.clear();
        this.currentPage = 0;
        this.nextCursor = 0;

        const listContainer = document.getElementById('follow-list-container');
        const emptyState = document.getElementById('empty-state');
        const loadingDiv = document.getElementById('loading-indicator');

        listContainer.innerHTML = '';
        emptyState.style.display = 'none';

        await this.loadFollowList();
    }

    hidePopup() {
        const overlay = document.getElementById('weibo-follow-overlay');
        const popup = document.getElementById('weibo-follow-popup');

        if (overlay) overlay.style.display = 'none';
        if (popup) popup.style.display = 'none';

        document.body.style.overflow = '';
    }

    async loadFollowList() {
        if (this.isLoading) return;

        this.isLoading = true;
        const loadingDiv = document.getElementById('loading-indicator');
        const listContainer = document.getElementById('follow-list-container');
        const emptyState = document.getElementById('empty-state');
        const loadMoreBtn = document.getElementById('load-more-btn');

        loadingDiv.style.display = 'block';
        loadMoreBtn.style.display = 'none';

        try {
            let pp = 0;
            while(++pp){
            const url = `https://m.weibo.cn/api/container/getIndex?containerid=231093_-_selffollowed&page=${pp+this.currentPage}`;
            const response = await fetch(url, {
                credentials: 'include' 
            });
            if (!response.ok) {
                throw new Error(`HTTP错误! 状态码: ${response.status}`);
            }
            let data = await response.json();


            if (data.ok !== 1) {
                throw new Error('API返回错误: ' + (data.msg || '未知错误'));
            }

            data.data.cards.forEach(cards => {
               (cards?.card_group??[]).forEach(u=>{
                   if(u.user){
                       let x = u.user;
                       const user = {
                            id: String(x.id),
                            name: x.screen_name || '未知用户',
                            remarkName:x.remark || "",
                            avatar: x.avatar_hd || x.avatar_large || '',
                            desc: `粉丝：${x.followers_count_str || '0'}${x.description?"<br>"+x.description:""}`,
                            isSubscribed: this.checkIfSubscribed(String(x.id)) 
                };
                this.users.push(user);
                   }
               })
            });
            this.nextCursor = data.data.cardlistInfo.page || 0;
            if(this.nextCursor == 0 || pp>=5){
                break
            }
           }

            this.renderUserList();
            this.updateStatus();

            if (this.users.length === 0) {
                emptyState.style.display = 'block';
            } else {
                emptyState.style.display = 'none';
            }

            if (this.nextCursor !== 0) {
                loadMoreBtn.style.display = 'block';
            }

        } catch (error) {
            console.error('加载关注列表失败:', error);

            const errorDiv = document.createElement('div');
            errorDiv.style.cssText = `
                text-align: center;
                padding: 40px 20px;
                color: #dc3545;
            `;
            errorDiv.innerHTML = `
                <div style="font-size: 48px; margin-bottom: 20px;">⚠️</div>
                <div style="font-size: 16px; margin-bottom: 10px;">加载失败</div>
                <div style="font-size: 14px; margin-bottom: 20px; color: #666;">${error.message}</div>
                <button onclick="window.weiboFollowManager.retryLoad()" class="control-btn">重试</button>
            `;

            listContainer.innerHTML = '';
            listContainer.appendChild(errorDiv);

        } finally {
            this.isLoading = false;
            loadingDiv.style.display = 'none';
        }
    }

    retryLoad() {
        const listContainer = document.getElementById('follow-list-container');
        listContainer.innerHTML = '';
        this.currentPage = 0;
        this.nextCursor = 0;
        this.users = [];
        this.loadFollowList();
    }

    async loadMore() {
        this.currentPage += 5;
