    sortTypeSelect.value = urlParams.get('sortType') || '2';
    isFinishSelect.value = urlParams.get('isfinish') || '0';
    sortTypeSelect.onchange = () => {
        updateUrlParam('sortType', sortTypeSelect.value);
        window.scrollTo(0,0);
    }
    isFinishSelect.onchange = () => {
        updateUrlParam('isfinish', isFinishSelect.value);
        window.scrollTo(0,0);
    }


    initScrollListener();
    createBookElements(jsonData,offset);
    updateCurrentPage();

    const checkScrollable = () => {
        if (document.body.scrollHeight <= window.innerHeight) {

            if (hasMore) {
                loadNextPage();
            } else if (hasPrevious) {
                loadPreviousPage();
            }
        }
    };


    checkScrollable();
}



