let doc = org.jsoup.Jsoup.parse(result);
let infoTitle = doc.select("h1").text();

// --- 介绍页内容保持不变 ---
let infoTable = "";
let rows = doc.select(".mt-2 dl.row dt"); 
for (let j = 0; j < rows.size(); j++) {
    let dt = rows.get(j);
    let dd = dt.nextElementSibling(); 
    if (dt && dd) {
        let parts = dd.html().split('href="/');
        let ddContent = parts.join('href="https://www.v2ph.ru/');
        infoTable += "<tr><td style='font-weight:bold;padding-right:10px;white-space:nowrap;vertical-align:top;'>" + dt.text() + "</td><td>" + ddContent + "</td></tr>";
    }
}

let allPhotos = [];
let currentHtml = result;
let baseUrl = "https://www.v2ph.ru";

// --- 分页抓取图片 ---
while (currentHtml) {
    let currentDoc = org.jsoup.Jsoup.parse(currentHtml);
    let imgs = currentDoc.select("img.album-photo");
    for (let i = 0; i < imgs.size(); i++) {
        let src = imgs.get(i).attr("data-src");
        if (src) {
            // 保持图片宽度 100%
            allPhotos.push("<img src='" + src + "' style='width:100%; display:block; margin-bottom:10px;'>");
        }
    }

    let nextBtn = currentDoc.select("ul.pagination li.page-item a[rel=next]").attr("href");
    if (nextBtn && nextBtn.indexOf("page=") !== -1) {
        let nextUrl = (nextBtn.indexOf("http") === 0) ? nextBtn : baseUrl + nextBtn;
        currentHtml = java.ajax(nextUrl);
    } else {
        currentHtml = null;
    }
}

// --- 将图片区域包裹在黑色背景容器中 ---
"<div><h1>" + infoTitle + "</h1><table style='width:100%; border-collapse:collapse; line-height:1.6;'>" + infoTable + "</table></div>" + 
"<div style='background-color:#000000; margin: 20px -16px; padding: 10px 0;'>" + 
allPhotos.join('') + 
"</div>";

